// Re-run after editing php-connector/api/*:  node scripts/build-php-bundle.js
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const lead = fs.readFileSync(path.join(root, 'php-connector/api/lead.php'), 'utf8');
const ht = fs.readFileSync(path.join(root, 'php-connector/api/.htaccess'), 'utf8');
fs.writeFileSync(path.join(root, 'builder/php-bundle.js'), '/* generated by scripts/build-php-bundle.js — do not edit */\nwindow.LP_PHP=' + JSON.stringify({ lead, htaccess: ht }) + ';\n');
console.log('builder/php-bundle.js written');
